def perfect_number():
    sum, count, number = 0, 0, 1
    top = input("enter a top value: ")

    while number < top:
        for i in range(1, number/2+1):
            if number/i*i == number:
                sum += i
        if sum == number:
            count += 1
            print count, ".perfect number: ", number

        number += 1
        sum = 0

    if count == 0:
        print "any perfect number in this range"


if __name__ == '__main__':
    perfect_number()

def ShellSort(A):
    def GetCols(n):
        cols = [1]
        val = 1
        while val < n:
            val = int(val * 2.2)
            cols.insert(0, val)
        return cols

    for h in GetCols(len(A)):
        for i in range(h, len(A)):
            cur = A[i]
            j = i
            while j >= h and A[j - h] > cur:
                A[j] = A[j - h]
                j -= h
            A[j] = cur

