def maxSumSub(arr):
    maxSums = [0]*len(arr)
    for i in range(len(arr)):
        Si = arr[i]
        maxS = Si
        for j in range(0,i):
            if (arr[j] < arr[i]):
                s = maxSums[j] + arr[i]
                if (s > maxS):
                    maxS = s
        maxSums[i] = maxS
    return max(maxSums)



