def replace_0_5_iterative(user_input):
    modified = []
    for i in user_input:
        if i == "0":
            modified.append("5")
        else:
            modified.append(i)
    return "".join(modified)


def replace_0_5_pythonic(user_input):
    return user_input.replace("0", "5")


