Since $\angle YWX=90^{\circ},$ $\triangle YWX$ is right angled. By the Pythagorean Theorem, $17^2=YW^2+15^2$ or $YW^2=17^2-15^2$ or $YW^2=289-225=64,$ and so $YW=\sqrt{64}=8,$ since $YW>0.$

We rotate $\triangle XWY$ clockwise $90^{\circ}$ about $W$ and similarly rotate $\triangle ZWY$ counter-clockwise $90^{\circ}$ about $W$ to obtain a new isosceles triangle with the same area. The new triangle formed has two equal sides of length $17$ (since $XY$ and $ZY$ form these sides) and a third side having length twice that of $YW$ or $2\times8=16$ (since the new base consists of two copies of $YW$).

Therefore, the desired perimeter is $17+17+16= \boxed{50}.$

from scipy.spatial import distance as dist

class Searcher:
	def __init__(self, index):
		self.index = index
	def search(self, queryFeature):
		results = {}
		for (k, feature) in self.index.items():
			d = dist.euclidean(queryFeature, feature)
			results[k] = d
		results = sorted([(v, k) for (k, v) in results.items()])
		return results

"""
Compiler objects for postgres data definition language.
"""

from sqlalchemy.sql.expression import Executable, ClauseElement
from sqlalchemy.ext.compiler import compiles


class CreateTableAs(Executable, ClauseElement):

    def __init__(self, name, query):
        self.name = name
        self.query = query


@compiles(CreateTableAs, "postgresql")
def _create_table_as(element, compiler, **kw):
    return "CREATE TABLE %s AS %s" % (
        element.name,
        compiler.process(element.query)
    )

